"""Optional Chromium synthetic-camera check; not an iPhone/Safari benchmark."""
from pathlib import Path
import argparse,json
from playwright.sync_api import sync_playwright
parser=argparse.ArgumentParser();parser.add_argument('--base',default='http://localhost:5182');parser.add_argument('--camera-feed',required=True);parser.add_argument('--output',required=True);parser.add_argument('--pixel-ratio',default='1');args=parser.parse_args();OUT=Path(args.output);OUT.mkdir(parents=True,exist_ok=True);BASE=args.base.rstrip('/')
FLAGS=['--no-sandbox','--disable-dev-shm-usage','--use-angle=swiftshader','--enable-unsafe-swiftshader','--use-fake-device-for-media-stream','--use-fake-ui-for-media-stream',f'--use-file-for-fake-video-capture={Path(args.camera_feed).resolve()}']
