with sync_playwright() as p:
 browser=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=FLAGS);ctx=browser.new_context(viewport={'width':393,'height':852},is_mobile=True,has_touch=True,accept_downloads=True);ctx.add_init_script(INIT);page=ctx.new_page();page.set_default_timeout(90000);page.on('pageerror',lambda e:result['errors'].append(str(e)));urls=[];page.on('request',lambda r:urls.append(r.url))
 page.goto(BASE+'/rainforest-ar.html',wait_until='networkidle');assert page.evaluate('__cameraCalls')==0;assert not any(u.endswith('.glb') for u in urls);page.screenshot(path=str(OUT/'mobile-intro.png'))
 page.get_by_role('button',name='Start camera',exact=True).click();page.locator('.ar-surface[data-sculpture="ready"]').wait_for(state='attached',timeout=90000);page.locator('#ar-root[data-tracking="found"]').wait_for(state='attached',timeout=120000);page.wait_for_timeout(4000);page.screenshot(path=str(OUT/'rainforest-tracked.png'));print('RAINFOREST TRACKED',flush=True)
 assert page.evaluate('__cameraCalls')==1;assert not any('mother-nature-golden-tree.glb' in u for u in urls);assert all(u.startswith(BASE) or u.startswith('blob:'+BASE) for u in urls)
 page.locator('.rainforest-lab').evaluate('(d)=>d.open=true');quality=page.locator('input[data-quality]');quality.evaluate("(i,v)=>{i.value=v;i.dispatchEvent(new Event('input',{bubbles:true}));}",args.pixel_ratio);height=page.locator('input[data-setting="height"]');height.evaluate("i=>{i.value='2.5';i.dispatchEvent(new Event('input',{bubbles:true}));}");assert page.locator('output[data-value="height"]').inner_text()=='2.5';page.get_by_role('button',name='Reset placement').click(force=True);assert height.input_value()=='3';page.get_by_role('button',name='Copy diagnostics',exact=True).click(force=True);(OUT/'normal-diagnostics.json').write_text(json.dumps(page.evaluate('__report'),indent=2));page.locator('.rainforest-lab').evaluate('(d)=>d.open=false')
 page.get_by_role('button',name='Record video',exact=True).click(force=True);page.get_by_role('button',name='Stop recording',exact=True).wait_for();page.wait_for_function('!document.querySelector("#ar-review").hidden||!document.querySelector("#ar-fallback").hidden',timeout=45000)
 page.wait_for_function('!document.querySelector("#ar-fallback").hidden||document.querySelector("#ar-clip").readyState>=2',timeout=30000)
 if page.locator('#ar-fallback').is_visible():
  result['recordingUsable']=False;result['nativeFallback']=True;page.screenshot(path=str(OUT/'native-recording-fallback.png'));page.get_by_role('button',name='Continue',exact=True).click(force=True)
 else:
  clip=page.locator('#ar-clip');clip.evaluate('v=>new Promise((ok,bad)=>{setTimeout(()=>bad("clip decode timeout"),20000);if(v.readyState>=2)return ok();v.onloadeddata=()=>ok();v.onerror=()=>bad("clip decode failed");})');result['clip']=clip.evaluate('v=>({duration:v.duration,width:v.videoWidth,height:v.videoHeight})');assert result['clip']['width']>0
  clip.evaluate('v=>v.currentTime=Math.max(0,v.duration-.5)');page.wait_for_timeout(800);page.screenshot(path=str(OUT/'recorded-review.png'))
  with page.expect_download() as download:page.get_by_role('link',name='Save video',exact=True).click(force=True)
  download.value.save_as(str(OUT/'rainforest-recorded.mp4'));result['clip']['bytes']=(OUT/'rainforest-recorded.mp4').stat().st_size
  page.get_by_role('button',name='Share video',exact=True).click(force=True);result['sharePlumbing']=page.evaluate('__shared');assert result['sharePlumbing']['gesture']
  result['recordingUsable']=result['clip']['duration']>=8
