 page.locator('.rainforest-lab').evaluate('d=>d.open=true');page.get_by_role('button',name='Copy diagnostics',exact=True).click(force=True);report=page.evaluate('__report');assert report['load']['state']=='ready';assert len(report['samples'])>0;result['diagnostics']=report;(OUT/'diagnostics.json').write_text(json.dumps(report,indent=2))
 page.get_by_role('button',name='Exit AR',exact=True).click(force=True);page.wait_for_url('**/coa/forest-and-flowers/mother-nature/original/');assert page.evaluate('__cameraStops')>=1
 result['cameraStopped']=True;result['noAutoCamera']=True;result['noGoldenModelRequest']=True;result['adjustmentControls']=True;result['passed']=not result['errors'];(OUT/'verification.json').write_text(json.dumps(result,indent=2));print({k:v for k,v in result.items() if k!='diagnostics'},flush=True);ctx.close();browser.close()
